package datatable

import (
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"
	"github.com/mattn/go-runewidth"

	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// TestRule116HoldsUnderEastAsianWidth pins Rule 116 when the terminal counts
// the ambiguous-width glyphs (● ○ ◐) as 2 cells. lipgloss always counts them as
// 1, so padding that trusts lipgloss overflows the row by one cell. It mutates
// the global runewidth condition, so it must not run in parallel.
func TestRule116HoldsUnderEastAsianWidth(t *testing.T) {
	prev := runewidth.DefaultCondition.EastAsianWidth
	runewidth.DefaultCondition.EastAsianWidth = true
	t.Cleanup(func() { runewidth.DefaultCondition.EastAsianWidth = prev })

	states := append([]indicator.State{indicator.Idle}, indicator.States()...)
	for _, width := range []int{60, 120} {
		for _, st := range states {
			for _, selected := range []bool{false, true} {
				name := st.String()
				m := New(indicatorConfig(nil))
				m.Resize(width, 10)
				m.SetItems([]row{{Name: "a", State: name}, {Name: "b", State: name}})
				if selected {
					cursorOn(t, &m, "a")
				} else {
					cursorOn(t, &m, "b")
				}
				want := m.RenderedWidth()
				// Line 0 is the header: its sort arrow (▲) is ambiguous-width
				// too, which is a separate, pre-existing matter out of scope here.
				for i, l := range strings.Split(m.View(), "\n")[1:] {
					plain := ansi.Strip(l)
					if plain == "" {
						continue
					}
					if got := runewidth.StringWidth(plain); got != want {
						t.Errorf("state=%s width=%d selected=%v line %d: East Asian width %d, want %d: %q",
							name, width, selected, i, got, want, plain)
					}
				}
			}
		}
	}
}
package datatable

import (
	"image/color"
	"strings"
	"testing"

	"charm.land/bubbles/v2/table"
	"charm.land/lipgloss/v2"
	"github.com/mattn/go-runewidth"

	"github.com/anthnel/devdesk/internal/testutil/colorprofile"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// withTrueColor forces the renderer to emit escape sequences for the duration
// of one test. Without it lipgloss detects no TTY, falls back to the Ascii
// profile and strips every colour — which would make every assertion in this
// file pass whatever the code does.
func withTrueColor(t *testing.T) {
	t.Helper()
	colorprofile.TrueColor(t)
}

// visible returns what a string puts on screen, escape sequences removed. The
// sequences are exactly what these tests are about, so the text has to be
// recoverable without them.
func visible(s string) string {
	var out strings.Builder
	for {
		before, rest, found := strings.Cut(s, "\x1b[")
		out.WriteString(before)
		if !found {
			return out.String()
		}
		if _, after, ok := strings.Cut(rest, "m"); ok {
			s = after
			continue
		}
		return out.String()
	}
}

// stateStyle colours the State column, which is what the views do with it.
func stateStyle(r row) lipgloss.Style {
	if r.State == "exited" {
		return lipgloss.NewStyle().Foreground(theme.ColorError)
	}
	return lipgloss.NewStyle().Foreground(theme.ColorOK)
}

func colouredConfig() Config[row] {
	cfg := testConfig()
	cfg.Columns[2].Style = stateStyle
	return cfg
}

func colouredTable(t *testing.T) Model[row] {
	t.Helper()
	m := New(colouredConfig())
	m.Resize(120, 10)
	m.SetItems(fixtures())
	return m
}

// rowLines returns the rendered rows, header excluded.
func rowLines(m *Model[row]) []string {
	return strings.Split(m.View(), "\n")[1:]
}

// ── The defect this file exists to make unexpressible ─────────────────────────

// The whole point. bubbles/table measured the cell value with runewidth before
// styling it, and runewidth counts an escape sequence's bytes as width: a
// seven-cell string carrying a colour measures 28, so it was truncated inside
// its own escape and the unterminated sequence bled over every row below.
//
// Colouring after the measurement means the visible width cannot depend on the
// colour, which is what this asserts directly.
}

// Rule 116 at the level it is actually seen: every rendered line spans the same
// width, so the viewport border closes on a rectangle.
func TestEveryRenderedLineSpansTheSameWidth(t *testing.T) {
	withTrueColor(t)
	m := colouredTable(t)
	m.Resize(100, 6)

	lines := strings.Split(m.View(), "\n")
	want := lipgloss.Width(lines[0])
	if want != 100-borderWidth {
		t.Errorf("the header spans %d cells, want %d", want, 100-borderWidth)
	}
	for i, line := range lines[1:] {
		if got := lipgloss.Width(line); got != want {
			t.Errorf("row %d spans %d cells, want %d", i, got, want)
		}
	}
}

// ── The scroll window ────────────────────────────────────────────────────────

func manyRows(n int) []row {
	out := make([]row, n)
	for i := range out {
		out[i] = row{Name: strings.Repeat("x", 1+i%9), Size: i % 5, State: "running"}
	}
	return out
}

// The window moves the least it can: it follows the cursor off its bottom edge
// one row at a time rather than recentring, which is what makes a long list
// readable while holding ↓.
func TestTheWindowFollowsTheCursorOffItsEdge(t *testing.T) {
	m := New(testConfig())
	_, busy := m.busyLabel(item)

	var line strings.Builder
	for i, c := range m.cfg.Columns {
		if i >= len(cols) || cols[i].Width <= 0 {
			continue
		}
		state := indicator.Idle
		if c.Indicator != nil {
			state = m.indicatorState(c, item, busy)
		}
		text := c.Cell(item)
		if state != indicator.Idle {
			text = indicator.Glyph(state, m.blinkOn)
			// Padded with runewidth, not lipgloss: lipgloss always counts an
			// ambiguous-width glyph as one cell, runewidth follows the terminal.
			fitted := runewidth.FillRight(text, cols[i].Width)
			line.WriteString(m.indicatorCellStyle(state, selected).Render(fitted))
			continue
		}
		fitted := fit(text, cols[i].Width, c.TruncateHead)
		if !busy && (!selected || m.preserveColumnColors) {
			if runs, ok := m.multiRunCell(c, item, fitted, selected); ok {
				line.WriteString(runs)
				continue
			}
