				}
				if got := runewidth.StringWidth(ansi.Strip(line)); got != want {
					t.Errorf("width %d, cursor on %q, line %d: runewidth %d, want %d (the two measures disagree)",
						width, selectedName, i, got, want)
				}
			}
		}
	}
}
