package zzchart
import ("testing";"strings";"regexp";"charm.land/lipgloss/v2";"github.com/anthnel/devdesk/internal/testutil/colorprofile")
var re = regexp.MustCompile("\x1b\\[[0-9;:]*m")
func stripANSI(s string) string { return re.ReplaceAllString(s,"") }
func rampTo(n int) []float64 { o:=make([]float64,n); for i:=range o {o[i]=float64(i%101)}; return o}
func TestWidth(t *testing.T){
 for _,w:=range []int{20,40,78,118}{ for _,h:=range []int{1,3,4}{
  l:=renderChart(rampTo(300),w,h,100)
  if len(l)!=h {t.Errorf("%dx%d: %d lines",w,h,len(l))}
  for i,x:=range l{ if g:=lipgloss.Width(x);g!=w{t.Errorf("%dx%d line %d width %d",w,h,i,g)}}}}
}
func TestBg(t *testing.T){
 colorprofile.TrueColor(t)
 sp:=make([]float64,40); for i:=range sp{ if i%8==0{sp[i]=90}}
 for _,h:=range []int{1,3,4}{ for i,line:=range renderChart(sp,40,h,100){
  if !strings.Contains(line,"\x1b["){t.Errorf("h%d line %d no styling %q",h,i,line)}
  if tail:=line[strings.LastIndex(line,"m")+1:];tail!=""{t.Errorf("h%d line %d tail %q",h,i,tail)}}}
}
func TestEmpty(t *testing.T){ for _,l:=range renderChart(nil,30,3,100){ if strings.TrimSpace(stripANSI(l))!=""{t.Error(l)}}}
func TestDump(t *testing.T){ colorprofile.TrueColor(t); for _,h:=range []int{1,3}{ for _,l:=range renderChart(rampTo(60),30,h,100){ t.Logf("%q",l)}}}
EOF
go test ./internal/ui/zzchart -v 2>&1 | tail -25

